#!/usr/bin/env python3
"""Author application/check of attempt-ledger-contract/1 over synthetic traces.
Reads: contract JSON, saved expectations, staged #685 expectations. No model/transport/historical checker is run.
Usage: python3 -I attempt-ledger-apply-0150.py  (cwd = repo root)"""
import json, hashlib, datetime, sys

H = lambda b: hashlib.sha256(b).hexdigest()
canon = lambda o: json.dumps(o, sort_keys=True, separators=(',', ':'), ensure_ascii=False)
RH = H(b'synthetic freeze receipt 0150')
SL = [('A-N', 'synthetic:review-pair-A', 'synthetic:01-N', 'no-tool'),
      ('A-T', 'synthetic:review-pair-A', 'synthetic:71-T', 'tool'),
      ('B-N', 'synthetic:review-pair-B', 'synthetic:02-N', 'no-tool'),
      ('B-T', 'synthetic:review-pair-B', 'synthetic:09-T', 'tool')]
ORDER = [s[0] for s in SL]
PAIRS = [('A-N', 'A-T'), ('B-N', 'B-T')]
PREC = ['hard_evidence_failure', 'settings_drift', 'budget']
STOPSTATE = {'hard_evidence_failure': 'stopped_hard_failure', 'settings_drift': 'stopped_settings_drift', 'budget': 'stopped_budget'}
HARD = {'DELIVERY_ONLY_UNPROVED', 'QUARANTINE', 'ROW_UNRESOLVED', 'BUNDLE_NO_ROW'}
RECOK = {'recovery_opened', 'evidence_gap_recorded', 'stop_recorded', 'plan_terminal', 'final_audit', 'submission_quarantined'}
POSTOK = {'submission_quarantined', 'evidence_gap_recorded', 'final_audit', 'audit_revision', 'delivery_retained'}


def ident(slot):
    for r, c, rep, arm in SL:
        if r == slot:
            return {'record_id': r, 'case_id': 'synthetic:review-case', 'pair_id': c, 'repetition_id': rep, 'arm': arm}
    return None if slot is None else {'record_id': slot, 'case_id': 'synthetic:unplanned', 'pair_id': 'x', 'repetition_id': 'x', 'arm': 'x'}


def ehash(e):
    return H(canon({k: v for k, v in e.items() if k != 'event_sha256'}).encode())


def seal(e):
    e['event_sha256'] = ehash(e)


def relink(ev, i):
    for k in range(i, len(ev)):
        ev[k]['prev_event_sha256'] = ev[k - 1]['event_sha256'] if k else None
        seal(ev[k])


class T:
    def __init__(s):
        s.ev = []; s.n = 0

    def add(s, typ, slot=None, seg='main', aid=None, did=None, order=None, p=None, pers='acknowledged', rh=None, claim=False):
        seq = len(s.ev) + 1
        e = {'ledger_id': 'L1', 'receipt_sha256': rh or RH, 'seq': seq, 'segment': seg, 'event_type': typ,
             'event_utc': (datetime.datetime(2026, 1, 1) + datetime.timedelta(seconds=seq)).strftime('%Y-%m-%dT%H:%M:%SZ'),
             'prev_event_sha256': s.ev[-1]['event_sha256'] if s.ev else None, 'persistence': pers,
             'producer': {'id': 'synthetic-producer', 'version': '1', 'authority_class': 'independently_verified' if claim else 'stipulated_synthetic'},
             'slot': ident(slot), 'slot_ref': slot, 'attempt_id': aid, 'attempt_order': order, 'delivery_id': did,
             'evidence_refs': [], 'payload': p or {}}
        seal(e); s.ev.append(e); return e

    def pre(s, ready=True):
        s.add('preflight_result', p={'outcome': 'ready' if ready else 'blocked', 'reasons': [] if ready else ['affordability'], 'receipt_status': 'stipulated_synthetic'})

    def res(s, slot, gate=True):
        s.add('reservation_made', slot, p={'gate': {k: gate for k in ('bindings_match', 'model_window_ok', 'evidence_ok', 'reservation_covers')},
                                           'reserved': {'tokens': 1000, 'time_s': 60, 'calls': 1}, 'remaining_after': {'tokens': 9000, 'time_s': 600, 'calls': 9}})

    def disp(s, slot, aid=None, pers='acknowledged', rh=None):
        s.n += 1; rq = ('request ' + slot).encode()
        s.add('dispatch_recorded', slot, aid=aid or 'att-' + slot, order=s.n, pers=pers, rh=rh, p={'request_sha256': H(rq), 'request_size': len(rq)})

    def deliv(s, slot, kind='dispatched', resp=b'answer', aid=None, did=None, evm=(), absent=False):
        aid = aid or 'att-' + slot; did = did or 'del-%s-1' % slot; order = None
        if kind == 'unsolicited':
            s.n += 1; order = s.n
        r = {'presence': 'absent', 'hex': None, 'size': None, 'sha256': None} if absent else \
            {'presence': 'present', 'hex': resp.hex(), 'size': len(resp), 'sha256': H(resp)}
        return s.add('delivery_retained', slot, aid=aid, did=did, order=order, p={'kind': kind, 'response': r, 'evidence_missing': list(evm)})

    def interp(s, slot, did, ans='ok', dec='ROW', proof='none', legacy=True, post=(True, True, True), aid=None):
        s.add('delivery_interpreted', slot, aid=aid or 'att-' + slot, did=did, claim=(proof == 'independently_verified'),
              p={'answer_class': ans, 'legacy_valid': legacy, 'proof': proof, 'decision': dec,
                 'postdispatch': dict(zip(('settings_match', 'model_ok', 'evidence_ok'), post))})

    def use(s, slot, aid=None, known=True, exh=False):
        s.add('usage_reconciled', slot, aid=aid or 'att-' + slot, p={'usage_known': known, 'tokens_in': 10 if known else None,
                                                                    'tokens_out': 5 if known else None, 'exhausted': exh, 'cost': None})

    def close(s, slot, cls):
        s.add('slot_closed', slot, p={'classification': cls})

    def stop(s, causes, primary=None, gate='predispatch', seg='main'):
        s.add('stop_recorded', seg=seg, p={'gate': gate, 'causes': causes, 'primary': primary or min(causes, key=PREC.index)})

    def term(s, state, seg='main'):
        s.add('plan_terminal', seg=seg, p={'state': state})

    def audit(s, rev, n, seg='main'):
        s.add('final_audit' if rev == 0 else 'audit_revision', seg=seg, p={'revision': rev, 'trigger_seqs': [], 'inventories': {'structural_comparisons': n}})

    def gap(s, slot, missing, seg='main'):
        s.add('evidence_gap_recorded', slot, seg=seg, p={'slot_ref': slot, 'missing': missing, 'irrecoverable': True})

    def recopen(s, last):
        s.add('recovery_opened', seg='recovery', p={'last_verified_seq': last, 'suspect_tail_seqs': [], 'reason': 'interruption'})


def cyc(t, slot, ans='ok', dec='ROW', cls='attempted_eligible', evm=(), known=True, absent=False, resp=b'answer',
        post=(True, True, True), legacy=True, mid=None, exh=False, gate=True):
    t.res(slot, gate); t.disp(slot)
    t.deliv(slot, resp=resp, evm=evm, absent=absent)
    t.interp(slot, 'del-%s-1' % slot, ans, dec, legacy=legacy, post=post)
    t.use(slot, known=known, exh=exh)
    if mid: mid(t)
    if cls: t.close(slot, cls)


def redel(t, slot, resp, dec, proof='none'):
    t.deliv(slot, 'redelivery', resp, did='del-%s-2' % slot)
    t.interp(slot, 'del-%s-2' % slot, 'ok', dec, proof=proof)


def extra(t, slot, aid, resp, dec):
    t.deliv(slot, 'unsolicited', resp, aid=aid, did='del-' + aid)
    t.interp(slot, 'del-' + aid, 'ok', dec, aid=aid)


# ------------------------------------------------------------------ analysis
def analyze(ev, real=False):
    out = {'viol': [], 'breaks': [], 'claims': set(), 'dec': [], 'audits': []}
    main = [e for e in ev if e['segment'] == 'main']; rec = [e for e in ev if e['segment'] == 'recovery']

    def prefix(lst, ps, psha, putc):
        ok = []
        for e in lst:
            code = None
            if e['seq'] != ps + 1: code = 'V02'
            elif e['prev_event_sha256'] != psha: code = 'V03'
            elif e['event_sha256'] != ehash(e): code = 'V04'
            elif putc and e['event_utc'] < putc: code = 'V05'
            elif e['persistence'] != 'acknowledged': code = 'V06'
            if code:
                out['breaks'].append((e['seq'], code)); break
            ok.append(e); ps, psha, putc = e['seq'], e['event_sha256'], e['event_utc']
        return ok
    okm = prefix(main, 0, None, None)
    lvs = okm[-1]['seq'] if okm else 0
    last = main[-1] if main else None
    okr = prefix(rec, last['seq'] if last else 0, last['event_sha256'] if last else None, last['event_utc'] if last else None)
    out['last_verified_seq'] = lvs
    verified = okm + okr
    vset = {id(e) for e in verified}
    touched = {e['slot_ref'] for e in ev if id(e) not in vset and e['slot_ref'] in ORDER}
    proof_by_did = {e['delivery_id']: e['payload'].get('proof') for e in ev if e['event_type'] == 'delivery_interpreted'}
    R = {s: dict(att=set(), disp=False, delivs=0, dec=None, ans=None, legacy=None, post=False, gap=False, bad=False, norow=False, cls=None) for s in ORDER}
    st = dict(phase='pre', stop=None, term=None, open=None, reserved={}, hard=False, last_order=0)
    seen_aid = set(); usage_seen = set(); delivs = {}; all_att = set(); ndisp = 0; quar = 0; stopev = None; nrev = 0

    def clos(r):
        if len(r['att']) > 1 or r['bad'] or r['gap'] or r['norow'] or (r['att'] and not r['disp']): return 'unresolved'
        if r['disp'] and r['dec'] == 'ROW' and r['ans'] == 'ok' and r['legacy'] and r['post']: return 'attempted_eligible'
        return 'attempted_ineligible'

    def unres_set():
        u = set(touched_bad)
        for s in ORDER:
            r = R[s]
            if (r['att'] or r['gap']) and clos(r) == 'unresolved': u.add(s)
            if r['disp'] and r['cls'] is None and st['term']: u.add(s)
        return u

    def struct():
        u = unres_set()
        return sum(1 for a, b in PAIRS if R[a]['cls'] == 'attempted_eligible' and R[b]['cls'] == 'attempted_eligible' and a not in u and b not in u)
    touched_bad = set(touched)
    for e in verified:
        t = e['event_type']; s = e['slot_ref']; p = e['payload']; codes = []
        if e['producer']['authority_class'] == 'independently_verified': out['claims'].add((e['seq'], 'V22'))
        if t == 'delivery_interpreted' and p.get('proof') == 'independently_verified': out['claims'].add((e['seq'], 'V22'))
        ph = st['phase']
        if real or e['receipt_sha256'] != RH: codes.append('V01')
        elif e['segment'] == 'recovery' and (t not in RECOK or (t == 'plan_terminal' and p['state'] != 'stopped_hard_failure')): codes.append('V13')
        elif ph == 'terminal' and (t not in POSTOK or (t == 'delivery_retained' and p['kind'] == 'dispatched')): codes.append('V17')
        elif ph == 'stopped' and t in ('reservation_made', 'dispatch_recorded'): codes.append('V18')
        else:
            nxt_res = next((x for x in ORDER if x not in st['reserved']), None)
            nxt_dsp = next((x for x in ORDER if not R[x]['disp']), None)
            if t == 'reservation_made':
                if st['open']: codes.append('V08')
                if s != nxt_res or e['slot'] != ident(s): codes.append('V07')
                if st['hard']: codes.append('V28')
            elif t == 'dispatch_recorded':
                if st['open'] and st['open'] != s: codes.append('V08')
                if s != nxt_dsp or e['slot'] != ident(s): codes.append('V07')
                if not st['reserved'].get(s): codes.append('V09')
                if e['attempt_id'] in seen_aid or (e['attempt_order'] or 0) <= st['last_order']: codes.append('V10')
            elif t == 'delivery_retained':
                r = p['response']; kind = p['kind']
                if r['presence'] == 'present':
                    b = bytes.fromhex(r['hex'])
                    if r['size'] != len(b) or r['sha256'] != H(b): codes.append('V12')
                if kind == 'dispatched' and not (st['open'] == s and R[s]['disp'] and R[s]['cls'] is None): codes.append('V23')
                if kind == 'unsolicited' and (e['attempt_id'] in seen_aid or (e['attempt_order'] or 0) <= st['last_order']): codes.append('V10')
                if not codes:
                    pr = proof_by_did.get(e['delivery_id']); pr = pr if pr == 'stipulated_synthetic' else 'none'
                    comp = not p['evidence_missing']; rep = s in ORDER and e['slot'] == ident(s)
                    rel = 'na'
                    if kind == 'redelivery':
                        prior = [d for d in delivs.values() if d['aid'] == e['attempt_id'] and d['kind'] != 'redelivery']
                        rel = 'no_prior' if not prior else ('identical' if prior[0]['sha'] == r['sha256'] else 'conflicting')
                    if kind == 'redelivery':
                        dec = 'QUARANTINE' if rel in ('conflicting', 'no_prior') else ('DELIVERY_ONLY' if pr != 'none' else 'DELIVERY_ONLY_UNPROVED')
                    elif kind == 'unsolicited':
                        dec = 'ROW_UNRESOLVED' if rep and comp else 'QUARANTINE'
                    else:
                        dec = 'ROW' if comp else 'BUNDLE_NO_ROW'
            elif t == 'delivery_interpreted':
                d = delivs.get(e['delivery_id'])
                if not d: codes.append('V11')
                elif p['decision'] != d['dec']: codes.append('V25')
            elif t == 'usage_reconciled':
                if e['attempt_id'] in usage_seen: codes.append('V24')
            elif t == 'slot_closed':
                if s in ORDER and p['classification'] != clos(R[s]): codes.append('V15')
            elif t == 'stop_recorded':
                if st['stop']: codes.append('V26')
                if p['primary'] != min(p['causes'], key=PREC.index): codes.append('V27')
            elif t == 'plan_terminal':
                if st['term']: codes.append('V20')
                if e['segment'] == 'main' and st['open']: codes.append('V16')
                if ph == 'blocked': der = 'blocked_preflight'
                elif st['stop']: der = STOPSTATE[st['stop']['primary']]
                else:
                    u = unres_set()
                    der = 'finished_complete' if all(R[x]['cls'] == 'attempted_eligible' and x not in u for x in ORDER) else 'finished_incomplete'
                if p['state'] != der: codes.append('V14')
                if p['state'].startswith('finished') and st['hard']: codes.append('V28')
            elif t in ('final_audit', 'audit_revision'):
                rc = struct()
                if p['inventories']['structural_comparisons'] != rc: codes.append('V19')
            elif t == 'recovery_opened':
                if p['last_verified_seq'] != lvs: codes.append('V21')
        if codes:
            for c in codes: out['viol'].append((e['seq'], c))
            if s in ORDER: touched_bad.add(s)
            if t == 'delivery_retained' and 'V12' in codes: pass
            continue
        # effects of a legal event
        if t == 'preflight_result': st['phase'] = 'open' if p['outcome'] == 'ready' else 'blocked'
        elif t == 'reservation_made': st['reserved'][s] = all(p['gate'].values()); st['open'] = s
        elif t == 'dispatch_recorded':
            R[s]['disp'] = True; R[s]['att'].add(e['attempt_id']); all_att.add(e['attempt_id']); seen_aid.add(e['attempt_id'])
            st['last_order'] = e['attempt_order']; ndisp += 1
        elif t == 'delivery_retained':
            kind = p['kind']; delivs[e['delivery_id']] = dict(aid=e['attempt_id'], kind=kind, sha=p['response']['sha256'], dec=dec, slot=s)
            out['dec'].append(dec)
            if kind in ('dispatched', 'unsolicited'):
                all_att.add(e['attempt_id']); seen_aid.add(e['attempt_id'])
                if kind == 'unsolicited': st['last_order'] = e['attempt_order']
            if s in ORDER:
                r = R[s]; r['delivs'] += 1
                if kind in ('dispatched', 'unsolicited'): r['att'].add(e['attempt_id'])
                if kind == 'dispatched': r['dec'] = dec
                if dec == 'BUNDLE_NO_ROW': r['norow'] = True
                if dec in ('DELIVERY_ONLY_UNPROVED', 'QUARANTINE', 'ROW_UNRESOLVED'): r['bad'] = True
            if dec == 'QUARANTINE': quar += 1
            if dec in HARD and st['phase'] not in ('terminal', 'stopped'): st['hard'] = True
        elif t == 'delivery_interpreted':
            d = delivs[e['delivery_id']]
            if d['kind'] == 'dispatched' and s in ORDER:
